def cells(g, pred):
    return [[1 if pred(v) else 0 for v in row] for row in g]
def bboxm(M):
    rs=[r for r,row in enumerate(M) for v in row if v]; cs=[c for r,row in enumerate(M) for c,v in enumerate(row) if v]
    if not rs: return None
    return min(rs),min(cs),max(rs),max(cs)
def diheds(K):
    res=[]
