    for rot in range(4):
        h=len(cur); w=len(cur[0])
        cur=[[cur[h-1-c][r] for c in range(w)] for r in range(h)]
        res.append(('r%d'%rot,[row[:] for row in cur]))
        res.append(('r%df'%rot,[row[::-1] for row in cur]))
    return res
